/*RTPS: {Currency}*/ /* Currency RTP is needed for the NSP_COGS script */ %Script(name:="NSP_PrintLog",application:="NetSuite",plantype:="NSP_NFS") Integer intLogLevel = operation.application.getSubstitutionVariableValue('NSP_SYS_LogLevel').replace('"','') as Integer Date startTime Date endTime /* Start runtime log */ startTime = new Date() printLines(intLogLevel, 0, "Process started at ${startTime.format("yyyy-MM-dd','HH:mm:ss:SSS z", TimeZone.getTimeZone('MST'))} 
") /* End log entry */ Cube cubPlan = operation.application.getCube("NSP_NFS") Dimension dimAcct = operation.application.getDimension("Account" , cubPlan) DataGrid grdForm = operation.getGrid() Map mapGrdForm = grdForm.getSourceInfo() Boolean blnCellsWereChanged = false List lstPovs = grdForm.getPov(); ArrayList arrlstPovFix = []; Set setChgdAccounts = new LinkedHashSet(); Set setChgdRelationships = new LinkedHashSet(); Set setChgdItems = new LinkedHashSet(); String strFcstYearPeriodIf = "IF ((@ISMBR(&NSP_PER_FcstCurrYr) AND @ISMBR(&NSP_PER_FcstCurrMo:TP12)) OR @ISMBR(&NSP_PER_FcstNextYr))" String strFcstYearPeriodEndIf = "ENDIF" /* Note: strFcstYearPeriodIf and strFcstYearPeriodEndIf are used by NSP_COGS_CConv and NSP_COGS scripts which are scripts also used by Budget Trending, so these values are not hardcoded */ String strCalcScript /* Always use the SetVersion User Variable as Version for the process. */ Dimension dimVersion = operation.application.getDimension("Version") UserVariable uvrSetVersion = dimVersion.getUserVariable('NSP_FIN_SetVersion') Member mbrSetVersion = uvrSetVersion.getValue() String strSetVersion = mbrSetVersion.getName() /* Determine form's POV/Page members for outermost FIX statement */ lstPovs.each() { if (it.dimName != 'Tracker' && it.dimName != 'Relationship' && it.dimName != 'Item' ) { arrlstPovFix.add([cscParams(it.mbrName)]); /* Both 'Relationship' and 'Item' can be on the rows of a form; they are excluded from 'arrlstPovFix' to prevent duplication */ } } /* Get the Account, Relationship, and Item members that have changed. To be used in inner FIX statements */ operation.grid.dataCellIterator('Ilvl0Descendants(Periods)').each { DataCell cell -> if(cell.edited) { blnCellsWereChanged = true setChgdAccounts lstIncomeAccts = dimAcct.getEvaluatedMembers("Lvl0Descendants(NFS_Income)", cubPlan).name if (lstIncomeAccts.contains (setChgdAccounts[0])) { strCalcScript = strCalcScript + """ FIX("NSP_Undefined_Location", "NSP_Undefined_Department", ${cscParams(setChgdRelationships, setChgdItems)}) FIX(${cscParams(setChgdAccounts)}) NSP_Load ( $strFcstYearPeriodIf %Script(name:="NSP_Revenue",application:="NetSuite",plantype:="NSP_NFS") $strFcstYearPeriodEndIf ) ENDFIX %Script(name:="NSP_COGS",application:="NetSuite",plantype:="NSP_NFS") $strRptCconvCOGS1 /* Variable comes from NSP_COGS_CConv script */ ENDFIX """ } /* Trending logic for Gross Margin input forms */ List lstGrossMargin = dimAcct.getEvaluatedMembers("NFS_Gross Margin %", cubPlan).name if (lstGrossMargin.contains (setChgdAccounts[0])) { strCalcScript = strCalcScript + """ FIX("NSP_Undefined_Location", ${cscParams(setChgdItems)}) FIX("NSP_Undefined_Class", "NSP_Undefined_Department", "NSP_Undefined_Relationship", "NFS_Gross Margin %") NSP_Load ( $strFcstYearPeriodIf %Script(name:="NSP_GrossMargin",application:="NetSuite",plantype:="NSP_NFS") $strFcstYearPeriodEndIf ) ENDFIX FIX(@RELATIVE("NSP_Total Class",0), @RELATIVE("NSP_Total Department",0), @RELATIVE("NSP_Total Relationship",0)) %Script(name:="NSP_COGS",application:="NetSuite",plantype:="NSP_NFS") $strRptCconvCOGS1 /* Variable comes from NSP_COGS_CConv script */ ENDFIX ENDFIX """ } /* Trending logic for Expense input forms */ List lstExpAccts = dimAcct.getEvaluatedMembers("Lvl0Descendants(NFS_Expense)", cubPlan).name if (lstExpAccts.contains (setChgdAccounts[0])) { strCalcScript = strCalcScript + """ FIX("NSP_Undefined_Location", "NSP_Undefined_Class", "NSP_Undefined_Item", "NSP_Undefined_Relationship", ${cscParams(setChgdAccounts)}) NSP_Load ( $strFcstYearPeriodIf %Script(name:="NSP_Expense",application:="NetSuite",plantype:="NSP_NFS") $strFcstYearPeriodEndIf ) ENDFIX """ } /* Trending logic for Balance Sheet Adj input forms */ List lstBalShtAccts = dimAcct.getEvaluatedMembers("Lvl0Descendants(NFS_Balance Sheet)", cubPlan).name if (lstBalShtAccts.contains (setChgdAccounts[0])) { strCalcScript = strCalcScript + """ FIX("NSP_Undefined_Item", "NSP_Undefined_Relationship") FIX(${cscParams(setChgdAccounts)}) %Script(name:="NSP_BalSht",application:="NetSuite",plantype:="NSP_NFS") ENDFIX %Script(name:="NSP_Plug_Account",application:="NetSuite",plantype:="NSP_NFS") ENDFIX """ } strCalcScript = strCalcScript + """ ENDFIX """ cubPlan.executeCalcScript(strCalcScript) /* Update runtime log */ printLines (intLogLevel, 2, "Form name: ${mapGrdForm.get("name")}") printLines (intLogLevel, 2, "Form Page/POV: ${cscParams(arrlstPovFix)}* 
 *Note: Excludes 'Relationship' and 'Item' members since they can both appear on form rows") printLines (intLogLevel, 2, "Changed Relationship members: ${cscParams(setChgdRelationships)}") printLines (intLogLevel, 2, "Changed Item members: ${cscParams(setChgdItems)}") printLines (intLogLevel, 2, "Changed Account members: ${cscParams(setChgdAccounts)} 
") printLines (intLogLevel, 1, "The following calc script was executed: 
 $strCalcScript") endTime = new Date() printLines (intLogLevel, 0, "Process ended at ${endTime.format("yyyy-MM-dd','HH:mm:ss:SSS z", TimeZone.getTimeZone('MST'))}") printElapsedTime(intLogLevel, 2, startTime, endTime) /* End log entry */

/*RTPS: {Currency}*/ /* Currency RTP is needed for the NSP_COGS script */ %Script(name:="NSP_PrintLog",application:="NetSuite",plantype:="NSP_NFS") Integer intLogLevel = operation.application.getSubstitutionVariableValue('NSP_SYS_LogLevel').replace('"','') as Integer Date startTime Date endTime /* Start runtime log */ startTime = new Date() printLines(intLogLevel, 0, "Process started at ${startTime.format("yyyy-MM-dd','HH:mm:ss:SSS z", TimeZone.getTimeZone('MST'))} 
") /* End log entry */ Cube cubPlan = operation.application.getCube("NSP_NFS") Dimension dimAcct = operation.application.getDimension("Account" , cubPlan) DataGrid grdForm = operation.getGrid() Map mapGrdForm = grdForm.getSourceInfo() Boolean blnCellsWereChanged = false List lstPovs = grdForm.getPov(); ArrayList arrlstPovFix = []; Set setChgdAccounts = new LinkedHashSet(); Set setChgdRelationships = new LinkedHashSet(); Set setChgdItems = new LinkedHashSet(); String strCalcScript /* Determine form's POV/Page members for outermost FIX statement */ lstPovs.each() { if (it.dimName != 'Tracker' && it.dimName != 'Relationship' && it.dimName != 'Item' ) { arrlstPovFix.add([cscParams(it.mbrName)]); /* Both 'Relationship' and 'Item' can be on the rows of a form; they are excluded from 'arrlstPovFix' to prevent duplication */ } } /* Get the Account, Relationship, and Item members that have changed. To be used in inner FIX statements */ operation.grid.dataCellIterator('Ilvl0Descendants(Periods)').each { DataCell cell -> if(cell.edited) { blnCellsWereChanged = true setChgdAccounts lstIncomeAccts = dimAcct.getEvaluatedMembers("Lvl0Descendants(NFS_Income)", cubPlan).name if (lstIncomeAccts.contains (setChgdAccounts[0])) { strCalcScript = strCalcScript + """ FIX("NSP_Undefined_Location", "NSP_Undefined_Department", ${cscParams(setChgdRelationships, setChgdItems)}) FIX(${cscParams(setChgdAccounts)}) NSP_Load ( IF ((@ISMBR(&NSP_PER_FcstCurrYr) AND @ISMBR(&NSP_PER_FcstCurrMo:TP12)) OR @ISMBR(&NSP_PER_FcstNextYr)) %Script(name:="NSP_Revenue",application:="NetSuite",plantype:="NSP_NFS") ENDIF ) ENDFIX %Script(name:="NSP_COGS",application:="NetSuite",plantype:="NSP_NFS") $strRptCconvCOGS1 /* Variable comes from NSP_COGS_CConv script */ ENDFIX """ } /* Trending logic for Gross Margin input forms */ List lstGrossMargin = dimAcct.getEvaluatedMembers("NFS_Gross Margin %", cubPlan).name if (lstGrossMargin.contains (setChgdAccounts[0])) { strCalcScript = strCalcScript + """ FIX("NSP_Undefined_Location", ${cscParams(setChgdItems)}) FIX("NSP_Undefined_Class", "NSP_Undefined_Department", "NSP_Undefined_Relationship", "NFS_Gross Margin %") NSP_Load ( IF ((@ISMBR(&NSP_PER_FcstCurrYr) AND @ISMBR(&NSP_PER_FcstCurrMo:TP12)) OR @ISMBR(&NSP_PER_FcstNextYr)) %Script(name:="NSP_GrossMargin",application:="NetSuite",plantype:="NSP_NFS") ENDIF ) ENDFIX FIX(@RELATIVE("NSP_Total Class",0), @RELATIVE("NSP_Total Department",0), @RELATIVE("NSP_Total Relationship",0)) %Script(name:="NSP_COGS",application:="NetSuite",plantype:="NSP_NFS") $strRptCconvCOGS1 /* Variable comes from NSP_COGS_CConv script */ ENDFIX ENDFIX """ } /* Trending logic for Expense input forms */ List lstExpAccts = dimAcct.getEvaluatedMembers("Lvl0Descendants(NFS_Expense)", cubPlan).name if (lstExpAccts.contains (setChgdAccounts[0])) { strCalcScript = strCalcScript + """ FIX("NSP_Undefined_Location", "NSP_Undefined_Class", "NSP_Undefined_Item", ${cscParams(setChgdAccounts)}) NSP_Load ( IF ((@ISMBR(&NSP_PER_FcstCurrYr) AND @ISMBR(&NSP_PER_FcstCurrMo:TP12)) OR @ISMBR(&NSP_PER_FcstNextYr)) %Script(name:="NSP_Expense",application:="NetSuite",plantype:="NSP_NFS") ENDIF ) ENDFIX """ } /* Trending logic for Balance Sheet Adj input forms */ List lstBalShtAccts = dimAcct.getEvaluatedMembers("Lvl0Descendants(NFS_Balance Sheet)", cubPlan).name if (lstBalShtAccts.contains (setChgdAccounts[0])) { strCalcScript = strCalcScript + """ FIX("NSP_Undefined_Item", "NSP_Undefined_Relationship") FIX(${cscParams(setChgdAccounts)}) %Script(name:="NSP_BalSht",application:="NetSuite",plantype:="NSP_NFS") ENDFIX %Script(name:="NSP_Plug_Account",application:="NetSuite",plantype:="NSP_NFS") ENDFIX """ } strCalcScript = strCalcScript + """ ENDFIX """ cubPlan.executeCalcScript(strCalcScript) /* Update runtime log */ printLines (intLogLevel, 2, "Form name: ${mapGrdForm.get("name")}") printLines (intLogLevel, 2, "Form Page/POV: ${cscParams(arrlstPovFix)}* 
 *Note: Excludes 'Relationship' and 'Item' members since they can both appear on form rows") printLines (intLogLevel, 2, "Changed Relationship members: ${cscParams(setChgdRelationships)}") printLines (intLogLevel, 2, "Changed Item members: ${cscParams(setChgdItems)}") printLines (intLogLevel, 2, "Changed Account members: ${cscParams(setChgdAccounts)} 
") printLines (intLogLevel, 1, "The following calc script was executed: 
 $strCalcScript") endTime = new Date() printLines (intLogLevel, 0, "Process ended at ${endTime.format("yyyy-MM-dd','HH:mm:ss:SSS z", TimeZone.getTimeZone('MST'))}") printElapsedTime(intLogLevel, 2, startTime, endTime) /* End log entry */

Account.formula:
/* Gets the correct Price value per Item.  
   Checks if there is Customer specific Price.  Otherwise, uses Period specific price.
   Note: Items must have a default Price set on the [NetSuite Item Price] form. 
/* Customer Price Adjustment */
IF ("NSP_Undefined_Class"->"SalesPriceInput" != #missing) 
	"SalesPriceInput" * (1 + "SalesPriceAdj%");

/* From [Price Adjustment (Period)] form */
ELSE  
	"NSP_Undefined_Class"->"NSP_Undefined_Relationship"->"SalesPriceInput";
ENDIF

IF (@ISMBR (&NSP_PER_FcstCurrYr))
 IF ("TP-Index" == "Merit Month"->"BegBalance"->&WF_NoIntersection)
  "PayRate"->&NSP_PER_FcstCurrYr->"BegBalance" * (1 + "Merit%"->"BegBalance");
 ELSE
  @PRIOR ("Adjusted Wage Rate");
 ENDIF
ELSEIF (@ISMBR (&NSP_PER_FcstNextYr))
 IF (@ISMBR ("TP1"))
  @PRIOR ("Adjusted Wage Rate"->"TP12", 1, @CHILDREN ("Years"));
 ELSEIF ("TP-Index" == "Merit Month"->"BegBalance"->&WF_NoIntersection)
  @PRIOR ("Adjusted Wage Rate") * (1 + "Merit%"->&NSP_PER_FcstCurrYr->"BegBalance");
 ELSE
  @PRIOR ("Adjusted Wage Rate");
 ENDIF
ENDIF

/* Salaried Employees */
IF("SalBasis"->&WF_Year == 1) "SalRate"->&WF_Year / 12;

/* Hourly Employees 
("SalRate"->&WF_Year * "HrsDay"->&WF_NoIntersection) * 1; 
@SUM(@RANGE("DaysMonth"->&NSP_PER_FcstCurrYr->&WF_NoIntersection,TP1:TP12))/ 12*/
ELSEIF ("SalBasis"->&WF_Year == 2)
("SalRate"->&WF_Year * "WorkingHours"->&WF_NoIntersection->&NSP_PER_FcstCurrYr) * 
@SUM(@RANGE("DaysMonth"->&NSP_PER_FcstCurrYr->&WF_NoIntersection,TP1:TP12))/ 12; 

ELSEIF ( @ISMBR("TE") )

	@SUMRANGE("PayRate",@RELATIVE("TE",0));

ENDIF

IF ("Status" ==1 )
	IF ( "FY-Index" > @CalcMgrGetYear("CalcStartDate"->&WF_Year) )
  		IF( @ISMBR(&NSP_PER_FcstCurrYr) )
    		/* Forecast Year 1 - Calculate merit starting with the time period input on the Annual Assumptions form and the Merit% entered on the Company Roster */
      		      		IF ( @ISMBR(@MEMBER(@CONCATENATE("HSP_ID_",@HspNumToString("MeritMonth"->&WF_NoIntersection->&NSP_PER_FcstCurrYr->BegBalance))):TP12) )  
      		"Salary" * "Merit%"->&WF_Year;
      		ELSE #missing; ENDIF

    /* Forecast Year 2 */
    ELSEIF ( @ISMBR(&NSP_PER_FcstNextYr) )  

	IF ( ("FY-Index" - 1) == @CalcMgrGetYear("CalcStartDate"->&WF_Year) )
       	IF( @ISMBR(@MEMBER(@CONCATENATE("HSP_ID_",@HspNumToString("MeritMonth"->&WF_NoIntersection->&NSP_PER_FcstCurrYr->BegBalance))):TP12) )
        "Salary" * "Merit%"->&WF_Year;
        ELSE #missing; 
        ENDIF

        ELSE

        IF ( @ISMBR(@MEMBER(@CONCATENATE("HSP_ID_",@HspNumToString("MeritMonth"->&WF_NoIntersection->&NSP_PER_FcstCurrYr->BegBalance))):TP12) ) 
       (("Salary"->TP12->&NSP_PER_FcstCurrYr + "Merit"->TP12->&NSP_PER_FcstCurrYr) * "Merit%"->&WF_Year);
        ELSE #missing; 
        "Salary" * "Merit%"->&WF_Year;
        ENDIF
	ENDIF
  	ELSE #missing; ENDIF
	ELSE #missing; ENDIF
ELSE #missing; ENDIF

IF (((@CalcMgrGetYear ("StartDate"->&WF_Year) * 100) + @CalcMgrGetMonth ("StartDate"->&WF_Year)) <= (("FY-Index" * 100) + "TP-Index")
AND ((@CalcMgrGetYear ("EndDate"->&WF_Year) * 100) + @CalcMgrGetMonth ("EndDate"->&WF_Year)) >= (("FY-Index" * 100) + "TP-Index"))
 IF ("Overtime%"->&WF_Year <> #Missing)
  ("Wages" + "Merit") * "Overtime%"->&WF_Year;
 ELSE
  #Missing;
 ENDIF
ELSE
 #Missing;
ENDIF

IF ( "Status" == 1  )  
	/* Allocate dental expenses from selected plan on the Company and Department Rosters */
    IF ( "Benefit_Plan_Dental"->&WF_Year != #missing )  
		&WF_Benefit->@MEMBER(@CONCATENATE("HSP_ID_",@HspNumToString("Benefit_Plan_Dental"->&WF_Year))) * "FTE"->&WF_Year;
	ENDIF
ELSE #missing; ENDIF

IF ( "Status" == 1  )  
	/* Allocate vision plan expenses from the selected plan on the Company and Department Rosters */
	IF ( "Benefit_Plan_Vision"->&WF_Year != #missing )  
		&WF_Benefit->@MEMBER(@CONCATENATE("HSP_ID_",@HspNumToString("Benefit_Plan_Vision"->&WF_Year))) * "FTE"->&WF_Year;
	ENDIF
ELSE #missing; ENDIF

IF (((@CalcMgrGetYear ("StartDate"->&WF_Year) * 100) + @CalcMgrGetMonth ("StartDate"->&WF_Year)) <= (("FY-Index" * 100) + "TP-Index")
AND ((@CalcMgrGetYear ("EndDate"->&WF_Year) * 100) + @CalcMgrGetMonth ("EndDate"->&WF_Year)) >= (("FY-Index" * 100) + "TP-Index"))
	/* Test for Active Status */
	IF ( "Status" == 1  )
		/* Check for participation */
		IF ("AD&D Plan"->&WF_Year == 1)
  		"Wages" * "AD&D Rate %"->BegBalance->&WF_NoIntersection * "FTE"->&WF_Year;
 		ELSE
  		#Missing;
 		ENDIF
	ELSE
 	#Missing;
	ENDIF
ENDIF

IF (((@CalcMgrGetYear ("StartDate"->&WF_Year) * 100) + @CalcMgrGetMonth ("StartDate"->&WF_Year)) <= (("FY-Index" * 100) + "TP-Index")
AND ((@CalcMgrGetYear ("EndDate"->&WF_Year) * 100) + @CalcMgrGetMonth ("EndDate"->&WF_Year)) >= (("FY-Index" * 100) + "TP-Index"))
/* Test for Active Status */
	IF ( "Status" == 1  )
		/* Check for participation */
		IF ("STD Plan"->&WF_Year == 1)
  		"Wages" * "STD Rate %"->BegBalance->&WF_NoIntersection * "FTE"->&WF_Year;
 		ELSE
  		#Missing;
 		ENDIF
	ELSE
 	#Missing;
	ENDIF
ENDIF

IF (((@CalcMgrGetYear ("StartDate"->&WF_Year) * 100) + @CalcMgrGetMonth ("StartDate"->&WF_Year)) <= (("FY-Index" * 100) + "TP-Index")
AND ((@CalcMgrGetYear ("EndDate"->&WF_Year) * 100) + @CalcMgrGetMonth ("EndDate"->&WF_Year)) >= (("FY-Index" * 100) + "TP-Index"))
/* Test for Active Status */
	IF ( "Status" == 1  )
		/* Check for participation */
		IF ("LTD Plan"->&WF_Year == 1)
  		"Wages" * "LTD Rate %"->BegBalance->&WF_NoIntersection * "FTE"->&WF_Year;
 		ELSE
  		#Missing;
 		ENDIF
	ELSE
 	#Missing;
	ENDIF
ENDIF

IF ("Status" == 1)
	IF ("401(k) Withholding %"->&WF_Year >= "401(k) Company Match %"->"BegBalance"->&NSP_SYS_CurrentScenario->&WF_NoIntersection) 
	/* Check if 401k expense has gone over match cap */
		IF ("401(k) Company Match Cap"->"BegBalance"->&WF_NoIntersection - @PRIOR("CYTD Taxable Earnings") * "401(k) Company Match %"->"BegBalance"->&NSP_SYS_CurrentScenario->&WF_NoIntersection <= 0)
	#missing;

	/* Check if prior period YTD match PLUS current period match does not exceed 401k match cap */
		ELSEIF (@PRIOR("CYTD Taxable Earnings") * "401(k) Company Match %"->"BegBalance"->&NSP_SYS_CurrentScenario->&WF_NoIntersection + 
	"Taxable Earnings" * "401(k) Company Match %"->"BegBalance"->&NSP_SYS_CurrentScenario->&WF_NoIntersection    <= "401(k) Company Match Cap"->"BegBalance"->&WF_NoIntersection) 
    "Taxable Earnings"->&NSP_SYS_CurrentScenario * "401(k) Company Match %"->"BegBalance"->&NSP_SYS_CurrentScenario->&WF_NoIntersection;

	/* Otherwise, calculate remaining 401k match */
		ELSE "401(k) Company Match Cap"->"BegBalance"->&WF_NoIntersection - @PRIOR("CYTD Taxable Earnings") * "401(k) Company Match %"->"BegBalance"->&NSP_SYS_CurrentScenario->&WF_NoIntersection;
		ENDIF
    ELSE 
    	/* Check if 401k expense has gone over match cap */
		IF ("401(k) Company Match Cap"->"BegBalance"->&WF_NoIntersection - @PRIOR("CYTD Taxable Earnings") * "401(k) Withholding %"->&WF_Year <= 0)
	#missing;

	/* Check if prior period YTD match PLUS current period match does not exceed 401k match cap */
		ELSEIF (@PRIOR("CYTD Taxable Earnings") * "401(k) Withholding %"->&WF_Year + 
	"Taxable Earnings" * "401(k) Withholding %"->&WF_Year    <= "401(k) company Match Cap"->"BegBalance"->&WF_NoIntersection) 
    "Taxable Earnings"->&NSP_SYS_CurrentScenario * "401(k) Withholding %"->&NSP_SYS_CurrentScenario->&WF_Year;

	/* Otherwise, calculate remaining 401k match */
		ELSE "401(k) Company Match Cap"->"BegBalance"->&WF_NoIntersection - @PRIOR("CYTD Taxable Earnings") * "401(k) Withholding %"->&WF_Year;
		ENDIF
   ENDIF
ENDIF

IF ("Status" == 1)
 IF ("CYTD Taxable Earnings" <= "FICAMax"->"BegBalance"->&WF_NoIntersection)
  "TaxEarn" * "FICA%"->"BegBalance"->&WF_NoIntersection;
 ELSEIF ("CYTD Taxable Earnings (Prior)" <= "FICAMax"->"BegBalance"->&WF_NoIntersection)
  ("FICAMax"->"BegBalance"->&WF_NoIntersection  - "CYTD Taxable Earnings (Prior)") * "FICA%"->"BegBalance"->&WF_NoIntersection;
 ELSE
  #Missing;
 ENDIF
ELSE
 #Missing;
ENDIF

IF ("Status" == 1)
	/* Calcualte Medicare expenses using the Medicare % input value on the Annual Assumptions form */
    "TaxEarn" * "Medicare%"->"BegBalance"->&WF_NoIntersection;
ELSE 
 #Missing; 
ENDIF

IF ("Status" == 1)
 IF ("CYTD Taxable Earnings" <= "FUTAMax"->"BegBalance"->&WF_NoIntersection)
  "TaxEarn" * "FUTA%"->"BegBalance"->&WF_NoIntersection;
 ELSEIF ("CYTD Taxable Earnings (Prior)" <= "FUTAMax"->"BegBalance"->&WF_NoIntersection)
  ("FUTAMax"->"BegBalance"->&WF_NoIntersection  - "CYTD Taxable Earnings (Prior)") * "FUTA%"->"BegBalance"->&WF_NoIntersection;
 ELSE
  #Missing;
 ENDIF
ELSE
 #Missing;
ENDIF

IF ("Status" == 1)
 IF ("CYTD Taxable Earnings" <= "SUTAMax"->"BegBalance"->&WF_NoIntersection)
  "TaxEarn" * "SUTA%"->"BegBalance"->&WF_NoIntersection;
 ELSEIF ("CYTD Taxable Earnings (Prior)" <= "SUTAMax"->"BegBalance"->&WF_NoIntersection)
  ("SUTAMax"->"BegBalance"->&WF_NoIntersection  - "CYTD Taxable Earnings (Prior)") * "SUTA%"->"BegBalance"->&WF_NoIntersection;
 ELSE
  #Missing;
 ENDIF
ELSE
 #Missing;
ENDIF

IF ("CYTD Taxable Earnings"<= "TaxEarn")
 #Missing;
ELSE
 "CYTD Taxable Earnings" - "TaxEarn";
ENDIF
